-- =========== NOTIFICATIONS ===========
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles(id) on delete cascade,
  kind text not null,
  title text not null,
  body text,
  link text,
  read_at timestamptz,
  created_at timestamptz default now()
);
create index if not exists notif_user_idx on notifications(user_id, created_at desc);

alter table notifications enable row level security;
-- AUDIT: (select auth.uid()) pattern confirmed — correct.
create policy "notif_read_own" on notifications for select
  using ((select auth.uid()) = user_id);
-- AUDIT: UPDATE allows user to mark read_at — correct. But no WITH CHECK to prevent
-- user from changing kind/title/body. Added with check.
create policy "notif_update_own" on notifications for update
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id); -- AUDIT: added with check
-- INSERT only via service_role (server pushes notifications). No client INSERT policy.
-- DELETE: user can delete own notifications.
create policy "notif_delete_own" on notifications for delete  -- AUDIT: added
  using ((select auth.uid()) = user_id);

